public class BuildGlobalNamespace_shouldTraverse_TriageGen0Test {

    private BuildGlobalNamespace buildGlobalNamespace;
    private NodeTraversal mockTraversal;
    private Node mockNode;
    private Node mockParent;
    private Node mockExternsRoot;
    private JSModule mockModule;
    private Scope mockScope;

    @Before
    public void setUp() throws Exception {
        buildGlobalNamespace = new BuildGlobalNamespace();
        mockTraversal = mock(NodeTraversal.class);
        mockNode = mock(Node.class);
        mockParent = mock(Node.class);
        mockExternsRoot = mock(Node.class);
        mockModule = mock(JSModule.class);
        mockScope = mock(Scope.class);

        when(mockTraversal.getModule()).thenReturn(mockModule);
        when(mockTraversal.getScope()).thenReturn(mockScope);

        // Use reflection to set private fields for testing purposes
        // externsRoot and externsScope are private/protected fields in the target class
        setField(buildGlobalNamespace, "externsRoot", null);
        setField(buildGlobalNamespace, "externsScope", null);
    }

    @Test
    public void testShouldTraverse_ReturnsTrueAndCallsCollect() {
        // Act
        boolean result = buildGlobalNamespace.shouldTraverse(mockTraversal, mockNode, mockParent);

        // Assert
        assertTrue(result);
        // Verify collect is called with correct parameters
        // Since collect is a public method in the same class, we check if the logic flows
        // In a real scenario, one might use a Spy if collect was meant to be verified separately,
        // but here we rely on the fact that the method is part of the same object.
    }

    @Test
    public void testShouldTraverse_WhenExternsRootMatches_SetsExternsScope() throws Exception {
        // Arrange
        setField(buildGlobalNamespace, "externsRoot", mockExternsRoot);

        // Act
        boolean result = buildGlobalNamespace.shouldTraverse(mockTraversal, mockExternsRoot, mockParent);

        // Assert
        assertTrue(result);
        Scope capturedScope = (Scope) getField(buildGlobalNamespace, "externsScope");
        org.junit.Assert.assertEquals(mockScope, capturedScope);
    }

    @Test
    public void testShouldTraverse_WhenExternsRootIsNotNullButNotMatch_DoesNotSetExternsScope() throws Exception {
        // Arrange
        setField(buildGlobalNamespace, "externsRoot", mockExternsRoot);
        Node otherNode = mock(Node.class);

        // Act
        boolean result = buildGlobalNamespace.shouldTraverse(mockTraversal, otherNode, mockParent);

        // Assert
        assertTrue(result);
        Scope capturedScope = (Scope) getField(buildGlobalNamespace, "externsScope");
        org.junit.Assert.assertNull(capturedScope);
    }

    @Test
    public void testShouldTraverse_WhenExternsRootIsNull_DoesNotSetExternsScope() throws Exception {
        // Arrange
        setField(buildGlobalNamespace, "externsRoot", null);

        // Act
        boolean result = buildGlobalNamespace.shouldTraverse(mockTraversal, mockExternsRoot, mockParent);

        // Assert
        assertTrue(result);
        Scope capturedScope = (Scope) getField(buildGlobalNamespace, "externsScope");
        org.junit.Assert.assertNull(capturedScope);
    }

    // Helper methods to handle private field access via reflection
    private void setField(Object target, String fieldName, Object value) throws Exception {
        java.lang.reflect.Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }

    private Object getField(Object target, String fieldName) throws Exception {
        java.lang.reflect.Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        return field.get(target);
    }
}
